/*\n  # Newsletter System Schema\n  \n  1. Table Extensions\n    - Extend `leads` table with email marketing fields:\n      - `first_name` (text) - Contact's first name\n      - `last_name` (text) - Contact's last name\n      - `company` (text) - Company name\n      - `tags` (text[]) - Array of tags for segmentation\n      - `opt_in` (boolean) - Email marketing consent, default false\n      - `unsubscribed` (boolean) - Unsubscribe status, default false\n  \n  2. New Tables\n    - `email_templates`\n      - `id` (uuid, primary key)\n      - `name` (text) - Template name\n      - `subject` (text) - Email subject line\n      - `html` (text) - Email HTML content\n      - `json_content` (jsonb) - Structured content for block editor\n      - `created_at` (timestamptz)\n      - `updated_at` (timestamptz)\n    \n    - `email_campaigns`\n      - `id` (uuid, primary key)\n      - `name` (text) - Campaign name\n      - `template_id` (uuid) - Foreign key to email_templates\n      - `segment_filter_json` (jsonb) - Audience filter criteria\n      - `status` (text) - draft, sending, sent, failed\n      - `sent_at` (timestamptz) - When campaign was sent\n      - `total_recipients` (integer) - Total number of recipients\n      - `delivered_count` (integer) - Successfully delivered\n      - `open_count` (integer) - Unique opens\n      - `click_count` (integer) - Unique clicks\n      - `bounce_count` (integer) - Bounces\n      - `created_by` (uuid) - Foreign key to profiles\n      - `created_at` (timestamptz)\n      - `updated_at` (timestamptz)\n    \n    - `email_sends`\n      - `id` (uuid, primary key)\n      - `campaign_id` (uuid) - Foreign key to email_campaigns\n      - `contact_id` (uuid) - Foreign key to leads\n      - `status` (text) - queued, sent, delivered, failed, bounced\n      - `provider_message_id` (text) - External provider message ID\n      - `sent_at` (timestamptz)\n      - `delivered_at` (timestamptz)\n      - `opened_at` (timestamptz)\n      - `clicked_at` (timestamptz)\n      - `open_count` (integer) - Number of opens\n      - `click_count` (integer) - Number of clicks\n      - `error_message` (text)\n      - `created_at` (timestamptz)\n    \n    - `email_events`\n      - `id` (uuid, primary key)\n      - `send_id` (uuid) - Foreign key to email_sends\n      - `provider_message_id` (text) - External provider message ID\n      - `event_type` (text) - delivered, open, click, bounce, spam, unsubscribe\n      - `timestamp` (timestamptz) - When event occurred\n      - `metadata` (jsonb) - Additional event data (URLs, user agent, etc.)\n      - `raw_payload` (jsonb) - Full webhook payload\n      - `created_at` (timestamptz)\n  \n  3. Security\n    - Enable RLS on all new tables\n    - Add policies for authenticated users to manage their campaigns\n    - Public access for unsubscribe functionality\n  \n  4. Indexes\n    - Index on email_sends(campaign_id, contact_id)\n    - Index on email_events(provider_message_id)\n    - Index on email_sends(provider_message_id)\n    - Index on leads(opt_in, unsubscribed) for filtering\n*/\n\n-- Extend leads table with email marketing fields\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM information_schema.columns \n    WHERE table_name = 'leads' AND column_name = 'first_name'\n  ) THEN\n    ALTER TABLE leads ADD COLUMN first_name text;
\n  END IF;
\n\n  IF NOT EXISTS (\n    SELECT 1 FROM information_schema.columns \n    WHERE table_name = 'leads' AND column_name = 'last_name'\n  ) THEN\n    ALTER TABLE leads ADD COLUMN last_name text;
\n  END IF;
\n\n  IF NOT EXISTS (\n    SELECT 1 FROM information_schema.columns \n    WHERE table_name = 'leads' AND column_name = 'company'\n  ) THEN\n    ALTER TABLE leads ADD COLUMN company text;
\n  END IF;
\n\n  IF NOT EXISTS (\n    SELECT 1 FROM information_schema.columns \n    WHERE table_name = 'leads' AND column_name = 'tags'\n  ) THEN\n    ALTER TABLE leads ADD COLUMN tags text[] DEFAULT '{}';
\n  END IF;
\n\n  IF NOT EXISTS (\n    SELECT 1 FROM information_schema.columns \n    WHERE table_name = 'leads' AND column_name = 'opt_in'\n  ) THEN\n    ALTER TABLE leads ADD COLUMN opt_in boolean DEFAULT false;
\n  END IF;
\n\n  IF NOT EXISTS (\n    SELECT 1 FROM information_schema.columns \n    WHERE table_name = 'leads' AND column_name = 'unsubscribed'\n  ) THEN\n    ALTER TABLE leads ADD COLUMN unsubscribed boolean DEFAULT false;
\n  END IF;
\nEND $$;
\n\n-- Create email_templates table\nCREATE TABLE IF NOT EXISTS email_templates (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name text NOT NULL,\n  subject text NOT NULL,\n  html text NOT NULL,\n  json_content jsonb,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);
\n\n-- Create email_campaigns table\nCREATE TABLE IF NOT EXISTS email_campaigns (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name text NOT NULL,\n  template_id uuid REFERENCES email_templates(id) ON DELETE SET NULL,\n  segment_filter_json jsonb DEFAULT '{}',\n  status text DEFAULT 'draft' CHECK (status IN ('draft', 'sending', 'sent', 'failed')),\n  sent_at timestamptz,\n  total_recipients integer DEFAULT 0,\n  delivered_count integer DEFAULT 0,\n  open_count integer DEFAULT 0,\n  click_count integer DEFAULT 0,\n  bounce_count integer DEFAULT 0,\n  created_by uuid REFERENCES profiles(id) ON DELETE SET NULL,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);
\n\n-- Create email_sends table\nCREATE TABLE IF NOT EXISTS email_sends (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  campaign_id uuid REFERENCES email_campaigns(id) ON DELETE CASCADE,\n  contact_id uuid REFERENCES leads(id) ON DELETE CASCADE,\n  status text DEFAULT 'queued' CHECK (status IN ('queued', 'sent', 'delivered', 'failed', 'bounced')),\n  provider_message_id text,\n  sent_at timestamptz,\n  delivered_at timestamptz,\n  opened_at timestamptz,\n  clicked_at timestamptz,\n  open_count integer DEFAULT 0,\n  click_count integer DEFAULT 0,\n  error_message text,\n  created_at timestamptz DEFAULT now()\n);
\n\n-- Create email_events table\nCREATE TABLE IF NOT EXISTS email_events (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  send_id uuid REFERENCES email_sends(id) ON DELETE CASCADE,\n  provider_message_id text,\n  event_type text NOT NULL CHECK (event_type IN ('delivered', 'open', 'click', 'bounce', 'spam', 'unsubscribe')),\n  timestamp timestamptz DEFAULT now(),\n  metadata jsonb DEFAULT '{}',\n  raw_payload jsonb,\n  created_at timestamptz DEFAULT now()\n);
\n\n-- Create indexes for performance\nCREATE INDEX IF NOT EXISTS idx_email_sends_campaign_contact ON email_sends(campaign_id, contact_id);
\nCREATE INDEX IF NOT EXISTS idx_email_sends_provider_msg_id ON email_sends(provider_message_id);
\nCREATE INDEX IF NOT EXISTS idx_email_events_provider_msg_id ON email_events(provider_message_id);
\nCREATE INDEX IF NOT EXISTS idx_email_events_send_id ON email_events(send_id);
\nCREATE INDEX IF NOT EXISTS idx_leads_opt_in_unsub ON leads(opt_in, unsubscribed);
\n\n-- Enable RLS on all new tables\nALTER TABLE email_templates ENABLE ROW LEVEL SECURITY;
\nALTER TABLE email_campaigns ENABLE ROW LEVEL SECURITY;
\nALTER TABLE email_sends ENABLE ROW LEVEL SECURITY;
\nALTER TABLE email_events ENABLE ROW LEVEL SECURITY;
\n\n-- RLS Policies for email_templates\nCREATE POLICY "Users can view all templates"\n  ON email_templates FOR SELECT\n  TO authenticated\n  USING (true);
\n\nCREATE POLICY "Users can create templates"\n  ON email_templates FOR INSERT\n  TO authenticated\n  WITH CHECK (true);
\n\nCREATE POLICY "Users can update templates"\n  ON email_templates FOR UPDATE\n  TO authenticated\n  USING (true)\n  WITH CHECK (true);
\n\nCREATE POLICY "Users can delete templates"\n  ON email_templates FOR DELETE\n  TO authenticated\n  USING (true);
\n\n-- RLS Policies for email_campaigns\nCREATE POLICY "Users can view all campaigns"\n  ON email_campaigns FOR SELECT\n  TO authenticated\n  USING (true);
\n\nCREATE POLICY "Users can create campaigns"\n  ON email_campaigns FOR INSERT\n  TO authenticated\n  WITH CHECK (true);
\n\nCREATE POLICY "Users can update campaigns"\n  ON email_campaigns FOR UPDATE\n  TO authenticated\n  USING (true)\n  WITH CHECK (true);
\n\nCREATE POLICY "Users can delete campaigns"\n  ON email_campaigns FOR DELETE\n  TO authenticated\n  USING (true);
\n\n-- RLS Policies for email_sends\nCREATE POLICY "Users can view all sends"\n  ON email_sends FOR SELECT\n  TO authenticated\n  USING (true);
\n\nCREATE POLICY "Users can create sends"\n  ON email_sends FOR INSERT\n  TO authenticated\n  WITH CHECK (true);
\n\nCREATE POLICY "Users can update sends"\n  ON email_sends FOR UPDATE\n  TO authenticated\n  USING (true)\n  WITH CHECK (true);
\n\n-- RLS Policies for email_events\nCREATE POLICY "Users can view all events"\n  ON email_events FOR SELECT\n  TO authenticated\n  USING (true);
\n\nCREATE POLICY "Public can create events"\n  ON email_events FOR INSERT\n  TO anon, authenticated\n  WITH CHECK (true);
\n\nCREATE POLICY "Users can update events"\n  ON email_events FOR UPDATE\n  TO authenticated\n  USING (true)\n  WITH CHECK (true);
;
